SetColumns(0);SetNthreads(1);SetQuitOnError(true);Alarm(250);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");X:=MDX11(2,28,GF(3));F0,mp:=AlgorithmicFunctionField(FunctionField(Curve(X)));F:=RationalExtensionRepresentation(F0);b,c:=Explode([F!mp(v):v in X`_coordinates]);assert Genus(F)eq 25;OF:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);print "Y228_AF_CUSP_MODEL_READY",Cputime(tt);E:=EllipticCurve([F|0,c,0,b*(1-b-c),0]);j:=jInvariant(E);print "Y228_AF_J_READY",Cputime(tt);cs:=Poles(j);assert {*Degree(P):P in cs*}eq {*1^^12,2^^6,3^^4,6^^2*};assert Degree(j)eq 576;print "D31B_Y228_AF_CUSP_COMPLETE",#cs,Sort([Degree(p):p in cs]),Cputime(tt);quit;
